def read(p):return json.loads((ROOT/p).read_text(encoding='utf-8'))
def main():
    config=read('project.json');audit=read('artifacts/audit.json');full=read('artifacts/full/metrics.json');sub=read('artifacts/subset/metrics.json');diag=read('artifacts/llm_diagnostics.json');abl=read('artifacts/full/ablations.json');env=read('artifacts/environment.json');model=read('artifacts/model_provenance.json')
