    out=ROOT/'output/pdf';out.mkdir(parents=True,exist_ok=True)
    fontdir=Path('C:/Windows/Fonts')
    if not fontdir.exists():fontdir=Path('/usr/share/fonts/truetype/dejavu')
    fontfiles=['times.ttf','timesbd.ttf','timesi.ttf'] if (fontdir/'times.ttf').exists() else ['DejaVuSerif.ttf','DejaVuSerif-Bold.ttf','DejaVuSerif-Italic.ttf']
    for name,file in zip(['Body','BodyBold','BodyItalic'],fontfiles):pdfmetrics.registerFont(TTFont(name,str(fontdir/file)))
    pdfmetrics.registerFontFamily('Body',normal='Body',bold='BodyBold',italic='BodyItalic',boldItalic='BodyBold')
    styles=getSampleStyleSheet();styles.add(ParagraphStyle(name='Paper',fontName='Body',fontSize=10.5,leading=14.2,alignment=TA_JUSTIFY,spaceAfter=8))
    styles.add(ParagraphStyle(name='PaperTitle',fontName='BodyBold',fontSize=19,leading=23,alignment=TA_CENTER,spaceAfter=15))
    styles.add(ParagraphStyle(name='Author',fontName='Body',fontSize=11,leading=15,alignment=TA_CENTER,spaceAfter=10))
    styles.add(ParagraphStyle(name='Section',fontName='BodyBold',fontSize=14,leading=18,spaceBefore=13,spaceAfter=9,keepWithNext=True))
    styles.add(ParagraphStyle(name='Subsection',fontName='BodyBold',fontSize=11.3,leading=15,spaceBefore=8,spaceAfter=6,keepWithNext=True))
