    def table(headers,rows,widths):
        values=[[Paragraph(html.escape(str(v)),styles['Cell']) for v in row] for row in [headers]+rows]
        t=Table(values,colWidths=widths,repeatRows=1,hAlign='CENTER');t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#e9eef2')),('VALIGN',(0,0),(-1,-1),'TOP'),('LINEBELOW',(0,0),(-1,0),.6,colors.HexColor('#56616a')),('LINEBELOW',(0,1),(-1,-1),.25,colors.HexColor('#d5d9dd')),('LEFTPADDING',(0,0),(-1,-1),5),('RIGHTPADDING',(0,0),(-1,-1),5),('TOPPADDING',(0,0),(-1,-1),5),('BOTTOMPADDING',(0,0),(-1,-1),5)]));story.append(t);story.append(Spacer(1,9))
